package com.bank.slips;

import java.util.logging.Logger;

public class TransactionList {
    private static final Logger log = Logger.getLogger(TransactionList.class.getName());

    // Three-pointer in-place reversal; returns the new head.
    public TxnNode reverse(TxnNode head) {
        TxnNode previous = null, current = head;
        while (current != null) {
            TxnNode next = current.next;   // save the rest before we overwrite
            current.next = previous;        // reverse this link
            previous = current;             // advance previous
            current = next;                 // advance current
        }
        log.fine("reverse complete; new head is the former tail");
        return previous;                    // previous is the new head
    }
}
