package com.bank.slips;

import java.util.logging.Logger;

public class ReverseDemo {
    private static final Logger log = Logger.getLogger(ReverseDemo.class.getName());

    public static void main(String[] args) {
        TxnNode head = build(new int[]{1, 2, 3});
        log.info("Original slip chain:  " + render(head));

        TxnNode reversed = new TransactionList().reverse(head);
        log.info("Reversed slip chain:  " + render(reversed));
    }

    static TxnNode build(int[] ids) {
        TxnNode dummy = new TxnNode(-1), tail = dummy;
        for (int id : ids) { tail.next = new TxnNode(id); tail = tail.next; }
        return dummy.next;
    }

    static String render(TxnNode n) {
        StringBuilder sb = new StringBuilder();
            while (n != null) { sb.append(n.slipId);
            if (n.next != null) sb.append(" -> "); n = n.next; }
        return sb.append(" -> null").toString();
    }
}
